const timeFormatter = new Intl.DateTimeFormat("de-DE", { hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23" });

function HeaderClock() {
  const [now, setNow] = useState<Date | null>(null);

  useEffect(() => {
    const updateTime = () => setNow(new Date());
    updateTime();
    const interval = window.setInterval(updateTime, 1000);
    document.addEventListener("visibilitychange", updateTime);
    window.addEventListener("focus", updateTime);
    return () => {
      window.clearInterval(interval);
      document.removeEventListener("visibilitychange", updateTime);
      window.removeEventListener("focus", updateTime);
    };
  }, []);

  return (
    <time className="header-clock" dateTime={now?.toISOString()} aria-label={now ? `Aktuelle Uhrzeit: ${timeFormatter.format(now)} Uhr` : "Aktuelle Uhrzeit wird geladen"}>
      <span aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="9" /><path d="M12 7v5l3 2" /></svg></span>
      {now ? timeFormatter.format(now) : "--:--:--"}
    </time>
  );
}

function AppLoadingScreen({ compact = false }: { compact?: boolean }) {
  return <main className={compact ? "content-loading-screen" : "loading-screen"} role="status" aria-live="polite" aria-label="Lernbereich wird geladen">
    <div className="loading-mark" aria-hidden="true">N</div>
    <div className="loading-copy">
      <b>{compact ? "Kapitel wird geöffnet" : "NotSan Prüfung wird vorbereitet"}</b>
      <span>{compact ? "Die benötigten Lerninhalte werden geladen …" : "Lernstand und Inhalte werden geladen …"}</span>
    </div>
    <div className="loading-progress" aria-hidden="true"><i /></div>
  </main>;
}

