type FlashcardSection = "definition" | "anatomy" | "pathophysiology" | "symptoms" | "complications" | "materials" | "initial" | "differentials" | "further";
type Flashcard = { question: string; answer: string };

const flashcardSets: Record<FlashcardSection, Flashcard[]> = {
  definition: [{ question: "Grenzen Sie den ischämischen vom hämorrhagischen Insult ab.", answer: "Ischämisch: Gefäßverschluss, ca. 80–85 %. Hämorrhagisch: Blutung, ca. 10–15 %." }],
  anatomy: [{ question: "Leiten Sie die arterielle Versorgung bis zum Circulus arteriosus cerebri her.", answer: "Versorgung über A. carotis interna und A. vertebralis. A. basilaris teilt sich in die Aa. cerebri posteriores; die Gefäße bilden den Circulus arteriosus cerebri (Willisii)." }, { question: "Welche zwei großen Venen bilden den hier relevanten venösen Abflussweg?", answer: "Innere Drosselvene (V. jugularis interna) → obere Hohlvene." }],
  pathophysiology: [{ question: "Stellen Sie die ischämische Schädigungskaskade vollständig dar.", answer: "Thrombus / Embolus → Gefäßverschluss → verminderte Perfusion → Infarktgebiet; Glukosemangel → Funktionsstörung der ATP-abhängigen Ionenpumpe; Kalziumeinstrom → freie Sauerstoffradikale → Zellschädigung; Natrium-Wassereinstrom → Hirnödem." }, { question: "Welche Folgen der Blutung führen beim hämorrhagischen Schlaganfall zur vitalen Gefahr?", answer: "Blutung verdrängt Hirngewebe → Hirndruckanstieg → Einklemmungsgefahr; Cushing-Triade beachten." }],
  symptoms: [{ question: "Mit welchen Befunden stützen Sie die Arbeitsdiagnose Schlaganfall?", answer: "Hemiparese / Hemiplegie, Fazialisparese, Aphasie, Sensibilitätsstörungen, Gesichtsfelddefekte, Doppelbilder, Gangunsicherheit, Schwindel, mögliche Bewusstseinsstörung und BEFAST mind. 1 positiv." }],
  complications: [{ question: "Entwickeln Sie die Gefahrenkette vom Hirnödem bis zum vitalen Versagen.", answer: "Hirnödem → Hirndrucksteigerung → Hirneinklemmung → Atem- und Kreislaufversagen." }],
  materials: [{ question: "Welche Einsatzmaterialien nehmen Sie zum vermuteten Schlaganfall mit?", answer: "EKG, Rucksack, Sauerstoff / Medumat, Medikamente, Absaugung, BZ und Zugang mind. Größe 18 G." }],
  initial: [{ question: "Strukturieren Sie Erstmaßnahmen und Anamnese beim Schlaganfall.", answer: "Kritisch / nicht kritisch, meist hämodynamisch stabil, BEFAST, Lagerung, SAMPLERS, NEF-Nachforderung, BZ und neurologische Tests. Besonders wichtig: Symptombeginn beziehungsweise letzter sicher symptomfreier Zeitpunkt, Verlauf, Antikoagulanzien oder Thrombozytenaggregationshemmer mit letzter Einnahme, relevante Vorgeschichte und bereits erfolgte Maßnahmen." }],
  differentials: [{ question: "Welche Differenzialdiagnosen müssen gegeneinander abgegrenzt werden?", answer: "Hypoglykämie; epileptischer Anfall / postiktaler Zustand; intrakranielle Blutung anderer Ursache, SHT; Meningitis / Enzephalitis; Migräne mit Aura; Intoxikationen und metabolische Entgleisungen." }],
  further: [{ question: "Welche Zeit-, Lagerungs- und Transportziele gelten?", answer: "30 Grad OKH, Versorgungszeit < 20 min, Prähospitalzeit < 60 min, Monitoring während Fahrt und telefonische Anmeldung." }, { question: "Wann und mit welchem Ziel erfolgt eine Blutdrucksenkung?", answer: "Nach VFA-Schlaganfall: 15 % bei > 220 / > 120." }],
};

type TrainingFlashcard = Flashcard & { id: string; area: string };

const collectedFlashcards: TrainingFlashcard[] = Object.entries(flashcardSets).flatMap(([area, cards]) => cards.map((card, index) => ({ ...card, id: `apoplex-card-${area}-${index + 1}`, area })));

const acsFlashcards: TrainingFlashcard[] = [
  { id: "acs-card-01", area: "Definition", question: "Ordnen Sie die drei Krankheitsbilder des akuten Koronarsyndroms voneinander ab.", answer: "ACS umfasst instabile Angina pectoris, NSTEMI und STEMI. STEMI: anhaltende ST-Hebung; NSTEMI: Infarkt ohne anhaltende ST-Hebung; instabile Angina: typische Beschwerden ohne ST-Hebung und ohne nachgewiesene Myokardnekrose." },
  { id: "acs-card-02", area: "Koronaranatomie", question: "Beschreiben Sie die arterielle Blutversorgung des Herzens.", answer: "Rechte und linke Koronararterie zweigen aus der Aorta ab. Die rechte Koronararterie versorgt unter anderem rechten Vorhof, rechte Kammer, Hinterwand und Teile des Reizleitungssystems. Die linke Koronararterie teilt sich in RCX und RIVA und versorgt große Teile des linken Herzens und der Kammerscheidewand." },
  { id: "acs-card-03", area: "Erregungsleitung", question: "Leiten Sie die normale kardiale Erregung vom Schrittmacherzentrum bis zum Arbeitsmyokard her.", answer: "Sinusknoten → Vorhöfe → AV-Knoten mit Verzögerung → His-Bündel → rechter und linker Tawara-Schenkel → Purkinje-Fasern → Kammermyokard." },
  { id: "acs-card-04", area: "Pathophysiologie", question: "Entwickeln Sie die zelluläre Schädigungskaskade vom Koronarverschluss bis zur Nekrose.", answer: "Minderperfusion → Sauerstoffmangel → Abfall der aeroben ATP-Produktion → anaerober Stoffwechsel mit Laktat und Azidose → Versagen ATP-abhängiger Ionenpumpen → Kaliumaustritt sowie intrazelluläre Natrium-, Wasser- und Kalziumansammlung → elektrische Instabilität und Kontraktionsverlust → anhaltende Ischämie → Nekrose." },
  { id: "acs-card-05", area: "Symptome", question: "Welche Befundkonstellation stützt die Arbeitsdiagnose ACS und bei wem ist eine atypische Präsentation besonders wichtig?", answer: "Retrosternaler Druck oder Schmerz mit Ausstrahlung, Dyspnoe, kalter Schweiß, Blässe, Übelkeit, Angst, Schwindel und Arrhythmien. Bei Frauen, Menschen mit Diabetes und Niereninsuffizienz können Dyspnoe, Schwäche oder Übelkeit ohne klassischen Thoraxschmerz dominieren." },
  { id: "acs-card-06", area: "EKG", question: "Welche präklinische Bedeutung haben ein unauffälliges Erst-EKG und das Zehn-Minuten-Ziel?", answer: "Ein unauffälliges Einzel-EKG schließt ACS nicht aus. Nach Thüringer VFA soll innerhalb von zehn Minuten ein 12-Kanal-EKG mit 50 mm/s geschrieben und beurteilt werden; Klinik und Verlauf bleiben entscheidend." },
  { id: "acs-card-07", area: "ST-Strecke / Infarktregionen", question: "Wie beurteilen Sie ST-Veränderungen und ordnen die wichtigsten Ableitungsgruppen zu?", answer: "ST-Veränderungen werden am J-Punkt in anatomisch zusammengehörigen Ableitungen und mit den ableitungs-, alters- und teilweise geschlechtsabhängigen Grenzwerten beurteilt. II, III und aVF sind inferior; I, aVL, V5 und V6 lateral; V1 bis V4 septal bis anterior. V3R/V4R prüfen eine Rechtsherzbeteiligung, V7 bis V9 einen posterioren Infarkt." },
  { id: "acs-card-08", area: "Gefahren", question: "Leiten Sie die beiden zentralen vitalen Gefahren eines akuten Myokardinfarkts her.", answer: "Elektrische Instabilität kann zu Kammerflimmern und Kreislaufstillstand führen. Verlust kontraktilen Myokards kann Herzinsuffizienz, Lungenödem, Hypotonie und kardiogenen Schock verursachen." },
  { id: "acs-card-09", area: "Erstmaßnahmen", question: "Strukturieren Sie das präklinische Vorgehen bei ACS-Verdacht bis zur Transportentscheidung.", answer: "Eigenschutz, cABCDE, körperliche Ruhe, Lagerung nach Kreislauf und Beschwerden, nicht laufen lassen, defibrillationsbereites Monitoring, 12-Kanal-EKG innerhalb von zehn Minuten, SAMPLERS und OPQRST, Sauerstoff nur nach VFA-Indikation sowie parallele NEF-, Zielklinik- und Transportplanung." },
  { id: "acs-card-10", area: "Differenzialdiagnosen", question: "Welche Befunde müssen vor einer antithrombotischen ACS-Therapie besonders an eine Aortendissektion denken lassen?", answer: "Reißender Schmerz zwischen den Schulterblättern, Blutdruckdifferenz über 20 mmHg zwischen den Armen, bekannte thorakale Aortenaneurysma, fehlende Leistenpulse oder einseitig fehlender Radialispuls sowie neurologisches Defizit." },
  { id: "acs-card-11", area: "Glyceroltrinitrat", question: "Welche Kontraindikationen gelten nach Thüringer VFA vor Glyceroltrinitrat-Spray?", answer: "PDE-5-Hemmer innerhalb der letzten 48 Stunden, systolischer Blutdruck unter 120 mmHg und Verdacht auf Hinterwandinfarkt." },
  { id: "acs-card-12", area: "VFA / Transport", question: "Welche Versorgungskette fordert der Thüringer ACS-Basisalgorithmus bei STEMI beziehungsweise neuem LSB?", answer: "cABCDE, zielgerichtete Sauerstoffgabe, 12-Kanal-EKG innerhalb zehn Minuten, Therapie nach den verknüpften Thüringer Algorithmen, frühzeitige Information einer Klinik mit Herzkatheterlabor einschließlich digitaler EKG-Übermittlung, Direktübergabe an das Herzkatheterlabor anstreben sowie kontinuierliches Monitoring und Transport." },
  { id: "acs-card-13", area: "O₂-Bilanz", question: "Welche Größen bestimmen Sauerstoffangebot und Sauerstoffbedarf des Myokards?", answer: "Das Angebot wird vor allem durch Koronarfluss und Sauerstoffgehalt des Blutes bestimmt. Herzfrequenz, Kontraktionskraft und Wandspannung bestimmen den Bedarf. Tachykardie ist doppelt ungünstig: Sie erhöht die Herzarbeit und verkürzt die für die Koronarperfusion wichtige Diastole. Ein reines Angebots-Bedarfs-Missverhältnis ist nicht automatisch ein atherothrombotisches Typ-1-ACS." },
  { id: "acs-card-14", area: "Stabil oder instabil", question: "Grenzen Sie stabile von instabiler Angina pectoris ab.", answer: "Stabile Angina ist reproduzierbar belastungsabhängig und folgt einem bekannten Muster. Instabil ist eine neu aufgetretene, in Ruhe bestehende, deutlich zunehmende oder länger anhaltende Angina; sie gehört zum ACS und lässt sich präklinisch nicht sicher vom NSTEMI trennen." },
  { id: "acs-card-15", area: "Diagnostik", question: "Welche drei Säulen führen von der ACS-Arbeitsdiagnose zur klinischen Einordnung?", answer: "Klinischer Kontext mit Beschwerden und Stabilität, 12-Kanal-EKG einschließlich Verlauf sowie hochsensitives Troponin im klinischen Verlauf. Präklinisch werden EKG und Klinik sofort bewertet; auf ein Troponinergebnis darf der zeitkritische Transport nicht warten." },
  { id: "acs-card-16", area: "EKG", question: "Was ist der J-Punkt und wann werden V3R/V4R oder V7–V9 ergänzt?", answer: "Der J-Punkt ist der Übergang vom Ende des QRS-Komplexes zur ST-Strecke und dient als Bezug der ST-Beurteilung. V3R/V4R helfen bei Verdacht auf Rechtsherzbeteiligung, V7–V9 bei möglichem posterioren Verschluss." },
  { id: "acs-card-17", area: "Pharmakologie", question: "Vergleichen Sie ASS und Heparin hinsichtlich Angriffspunkt und Wirkung.", answer: "ASS hemmt COX-1 irreversibel, senkt Thromboxan A₂ und damit die Thrombozytenaggregation. Unfraktioniertes Heparin verstärkt Antithrombin und hemmt besonders Thrombin sowie Faktor Xa. Beide bremsen die Thrombusprogression, lösen einen Koronarverschluss aber nicht mechanisch auf." },
  { id: "acs-card-18", area: "Heparingefahr", question: "Warum ist die heparininduzierte Thrombozytopenie Typ II trotz niedriger Thrombozytenzahl thrombotisch gefährlich?", answer: "HIT Typ II ist eine immunvermittelte Plättchenaktivierung. Dadurch sinkt die Thrombozytenzahl, gleichzeitig steigt das Risiko neuer arterieller oder venöser Thrombosen. Eine bekannte HIT muss vor Heparingabe berücksichtigt werden." },
];

const laeFlashcards: TrainingFlashcard[] = [
  { id: "lae-card-01", area: "Definition", question: "Definieren Sie die Lungenarterienembolie und erklären Sie die unmittelbare Folge hinter dem Verschluss.", answer: "Eine Lungenarterie oder einer ihrer Äste wird durch einen eingeschwemmten Embolus teilweise oder vollständig verschlossen. Hinter dem Verschluss bricht die Perfusion ein, während die Ventilation zunächst fortbestehen kann." },
  { id: "lae-card-02", area: "Physiologie", question: "Erklären Sie den alveolären Gasaustausch anhand der Partialdruckgefälle.", answer: "O₂ diffundiert wegen des höheren alveolären Partialdrucks aus den Alveolen in das venöse Blut. CO₂ diffundiert wegen seines höheren Partialdrucks im venösen Blut aus dem Blut in die Alveolen." },
  { id: "lae-card-03", area: "Ursachen", question: "Nennen Sie die Virchow-Trias und leiten Sie daraus das Thromboserisiko ab.", answer: "Veränderung der Blutströmung, der Gefäßwand und der Bluteigenschaften. Jede dieser Veränderungen begünstigt die Thrombusbildung; häufig liegt der Ursprung in tiefen Bein- oder Beckenvenen." },
  { id: "lae-card-04", area: "Embolusweg", question: "Beschreiben Sie den Weg eines venösen Thromboembolus bis zum Verschluss der Lungenstrombahn.", answer: "Tiefe Bein- oder Beckenvenen → venöses System → rechtes Herz → Truncus pulmonalis beziehungsweise Lungenarterien und deren Äste." },
  { id: "lae-card-05", area: "Pathophysiologie", question: "Entwickeln Sie die vollständige hämodynamische Gefahrenkette einer schweren LAE.", answer: "Gefäßverschluss → Ventilations-Perfusions-Mismatch und Hypoxämie → Widerstandsanstieg im Lungenkreislauf → akute Nachlasterhöhung des rechten Ventrikels → Rechtsherzinsuffizienz → sinkendes Herzzeitvolumen → Hypotonie und obstruktiver Schock." },
  { id: "lae-card-06", area: "Symptome", question: "Welche Befundkonstellation stützt präklinisch die Arbeitsdiagnose LAE?", answer: "Plötzliche Dyspnoe/Tachypnoe, Tachykardie, thorakaler oder atemabhängiger Schmerz, Synkope, Zyanose/Hypoxie, mögliche Hypotonie, gestaute Halsvenen sowie einseitige TVT-Zeichen. Die drei T sind Tachypnoe, Tachykardie und Thoraxschmerz." },
  { id: "lae-card-07", area: "EKG", question: "Erklären und bewerten Sie das vollständige S₁Q₃T₃-Muster.", answer: "Ausgeprägte S-Zacke in I, Q-Zacke in III und negative T-Welle in III. Das Muster kann eine akute Rechtsherzbelastung anzeigen, ist aber weder sensitiv noch beweisend für eine LAE." },
  { id: "lae-card-08", area: "Gefahren", question: "Warum ist der Schock bei massiver LAE primär obstruktiv und nicht einfach kardiogen?", answer: "Der Embolus behindert mechanisch die Lungenstrombahn. Dadurch steigt die rechtsventrikuläre Nachlast akut, das rechte Herz versagt und das Herzzeitvolumen sinkt. Ausgangspunkt ist die Obstruktion." },
  { id: "lae-card-09", area: "Erstmaßnahmen", question: "Strukturieren Sie die ersten präklinischen Maßnahmen bei Verdacht auf LAE.", answer: "Eigenschutz und Überblick, cABCDE, Basismaßnahmen, Ruhe und symptomgerechte Lagerung, Patient nicht laufen lassen, engmaschiges Monitoring einschließlich 12-Kanal-EKG, SAMPLERS, Notarzt- und Transportplanung, i.v. Zugang bei Indikation sowie Reanimationsbereitschaft." },
  { id: "lae-card-10", area: "Anamnese", question: "Welche LAE-spezifischen Punkte ergänzen Sie in SAMPLERS?", answer: "Immobilisation oder lange Reise, Operationen, frühere TVT/LAE, hormonelle Kontrazeption, Antikoagulation, Tumorerkrankung, Schwangerschaft, Exsikkose sowie einseitige Beinschwellung, Schmerz oder Rötung." },
  { id: "lae-card-11", area: "Differenzialdiagnosen", question: "Welche wichtigen Differenzialdiagnosen grenzen Sie präklinisch ab und mit welchen Hinweisen?", answer: "ACS/Myokardinfarkt, Lungenödem mit grobem Brodeln, Pneumonie mit feinem Brodeln, Pneumothorax, Asthma und Aortendissektion; bei letzterer Blutdruckseitenvergleich und periphere Pulse beachten." },
  { id: "lae-card-12", area: "Lyse / VFA", question: "Erklären Sie das Wirkprinzip der Lyse und ordnen Sie die Thüringer Zuständigkeit ein.", answer: "Aktivierung von Plasminogen zu Plasmin → Spaltung des stabilisierenden Fibrinnetzes → Auflösung des Thrombus. Anlage B2A führt Alteplase bei Lungenembolie nur für das NEF; Tenecteplase ist für LAE als erprobt, aber nicht zugelassen gekennzeichnet." },
];

const nierensteinkolikFlashcards: TrainingFlashcard[] = [
  { id: "nieren-card-01", area: "Definition", question: "Grenzen Sie Urolithiasis, Nephrolithiasis und Ureterolithiasis ab und erklären Sie, wann eine Kolik entsteht.", answer: "Urolithiasis bezeichnet Steinleiden im Harntrakt, Nephrolithiasis Steine in Niere/Nierenhohlsystem und Ureterolithiasis Harnleitersteine. Kolik entsteht vor allem bei akuter Abflussbehinderung mit Druck, Dehnung, Peristaltik gegen das Hindernis und lokaler Entzündung; ein Nierenstein kann symptomlos sein." },
  { id: "nieren-card-02", area: "Nierenfunktion", question: "Nennen Sie fünf zentrale Nierenfunktionen und ordnen Sie Aldosteron korrekt zu.", answer: "Ausscheidung; Regulation von Wasser/Elektrolyten und Säure-Basen-Haushalt; Renin/RAAS; Erythropoetin; Vitamin-D-Aktivierung. Aldosteron entsteht in der Nebennierenrinde, die Niere ist Zielorgan." },
  { id: "nieren-card-03", area: "Harnbildung", question: "Erklären Sie Primärharn, Filtration, Rückresorption, Sekretion und Endharn.", answer: "Filtration: Flüssigkeit/filtrierbare Stoffe aus Glomerulusblut in den Kapselraum; das Filtrat ist Primärharn. Rückresorption führt Stoffe aus dem Tubulus ins Blut zurück, Sekretion Stoffe aus Blut/Tubuluszellen ins Lumen. Übrig bleibt End- oder Sekundärharn." },
  { id: "nieren-card-04", area: "Anatomie", question: "Beschreiben Sie Harnweg und drei klassische Harnleiterengstellen.", answer: "Kelche → Nierenbecken → Harnleiter → Blase → Harnröhre. Engstellen: Übergang Nierenbecken/Harnleiter, Überkreuzung der Iliakalgefäße am Beckeneingang, Eintritt in die Blasenwand." },
  { id: "nieren-card-05", area: "Pathophysiologie", question: "Erklären Sie Steinbildung und Schmerzentstehung als zwei Ketten.", answer: "Übersättigung → Kristallbildung → Wachstum/Zusammenlagerung → Stein. Obstruktion → Druckanstieg oberhalb → Dehnung plus Peristaltik gegen das Hindernis und lokale Entzündung → starker kolikartiger Schmerz." },
  { id: "nieren-card-06", area: "Symptome", question: "Welche Befunde stützen eine Nierensteinkolik, ohne sie zu beweisen?", answer: "Plötzlicher wellenförmiger Flanken-/Rückenschmerz, Ausstrahlung in Unterbauch/Leiste/Genitale, Unruhe, Übelkeit/Erbrechen, vegetative Zeichen, Hämaturie sowie lageabhängig Harndrang, Pollakisurie oder Dysurie. Fehlende sichtbare Hämaturie schließt den Stein nicht aus." },
  { id: "nieren-card-07", area: "Begriffe", question: "Trennen Sie Harnstau, Harnverhalt, Oligurie und Anurie.", answer: "Harnstau: Rückstau oberhalb eines Hindernisses. Harnverhalt: Blase kann sich nicht ausreichend entleeren. Oligurie orientierend < etwa 500 ml/24 h, Anurie < etwa 100 ml/24 h beim Erwachsenen; Mengen allein diagnostizieren keine AKI." },
  { id: "nieren-card-08", area: "Warnzeichen", question: "Welche Konstellationen machen die vermutete Kolik besonders dringlich und warum?", answer: "Fieber/Schüttelfrost, Hypotonie, Bewusstseinsänderung, schlechter Allgemeinzustand, Anurie, Einzelniere oder unbeherrschbarer Schmerz. Besonders infizierte Obstruktion droht zur Urosepsis zu eskalieren und benötigt dringliche klinische Entlastung plus Antibiotika." },
  { id: "nieren-card-09", area: "Untersuchung", question: "Strukturieren Sie Ihre präklinische Untersuchung und Anamnese.", answer: "cABCDE; Bewusstsein, AF/SpO₂, Puls/RR, Temperatur, Haut/Kreislauf, NRS und Verlauf. OPQRST; frühere Steine, Infekt/Erbrechen, letzte Miktion/Urinmenge, Hämaturie/Dysurie, Nierenerkrankung/Einzelniere, Eingriffe, Medikamente/Allergien, Schwangerschaft und Gefäßrisiken. Abdomen/Flanken schonend untersuchen." },
  { id: "nieren-card-10", area: "Differenzialdiagnosen", question: "Welche lebens- oder organschädigenden Alternativen dürfen nicht übersehen werden?", answer: "Infizierte Obstruktion/Pyelonephritis, Aortenaneurysma oder -dissektion, akutes Abdomen/Peritonitis, EUG und andere gynäkologische Notfälle, Hodentorsion sowie bei passender atypischer Klinik ACS." },
  { id: "nieren-card-11", area: "VFA 39", question: "Leiten Sie den Thüringer Therapiepfad bei erwachsener Nierensteinkolik her.", answer: "Schwangerschaft und Stillzeit ausschließen; bei Schmerz oberhalb des Bauchnabels STEMI-Kriterien prüfen. Bei RRsys mindestens 100 mmHg nach Metamizol-Risikoaufklärung 1 g Metamizol als Kurzinfusion in 100 ml NaCl 0,9 % über fünf Minuten. Bei kolikartigem Schmerz zusätzlich 20 mg Butylscopolamin, mit 9 ml NaCl 0,9 % verdünnt, langsam geben. Kontinuierliches Monitoring und Transport." },
  { id: "nieren-card-12", area: "Flüssigkeit", question: "Warum wird ein Stein nicht mit forcierter Infusion oder Diuretika ‚ausgespült‘?", answer: "Mehr Flüssigkeit beseitigt die mechanische Obstruktion nicht zuverlässig und kann den Druck erhöhen. Volumen wird bedarfsgerecht bei tatsächlichen Verlusten oder Kreislaufproblem und unter Beachtung von Begleiterkrankungen gegeben." },
  { id: "nieren-card-13", area: "Transport", question: "Begründen Sie Zielklinik, Nachforderung und Übergabe.", answer: "Bei Instabilität, Sepsisverdacht oder unzureichender Symptomkontrolle ärztliche Unterstützung nachfordern. Geeignete Klinik, bei komplizierter Konstellation mit zeitnaher Urologie. SINNHAFT mit Beginn/Verlauf, Befunden, Urinausscheidung, Warnzeichen, Maßnahmen, Wirkung und Risiken." },
  { id: "nieren-card-14", area: "Fall", question: "Ein Patient mit Einzelniere berichtet Anurie und Flankenschmerz. Begründen Sie Ihre nächste Priorität.", answer: "Eine Obstruktion kann die gesamte Nierenfunktion gefährden. Nach cABCDE, Monitoring und Symptomkontrolle ist die Konstellation zeitkritisch urologisch abzuklären; keine Verzögerung durch Ausspülversuche." },
];

const shtFlashcards: TrainingFlashcard[] = [
  { id: "sht-card-01", area: "Definition", question: "Grenzen Sie Schädelprellung, geschlossenes SHT und offenes SHT voneinander ab.", answer: "Ein SHT setzt eine Verletzung von Gehirn oder Hirnhüllen durch äußere Gewalt voraus. Beim geschlossenen SHT besteht keine Verbindung nach außen; beim offenen SHT sind Kopfhaut, Schädel und Dura eröffnet, wodurch zusätzlich eine hohe Infektionsgefahr entsteht." },
  { id: "sht-card-02", area: "Anatomie", question: "Ordnen Sie die Schichten vom Schädelknochen bis zur Hirnoberfläche und die typischen Blutungsräume zu.", answer: "Schädelknochen → Epiduralraum → Dura mater → Subduralraum → Arachnoidea → Subarachnoidalraum → Pia mater. Epiduralblutung zwischen Knochen und Dura, Subduralblutung zwischen Dura und Arachnoidea, SAB zwischen Arachnoidea und Pia." },
  { id: "sht-card-03", area: "Mechanismus", question: "Erklären Sie Coup und Contrecoup anhand der Krafteinwirkung auf das Gehirn.", answer: "Coup bezeichnet die Verletzung am direkten Aufprallort. Contrecoup entsteht durch die Bewegung des Gehirns innerhalb des Schädels auf der gegenüberliegenden Seite." },
  { id: "sht-card-04", area: "Pathophysiologie", question: "Entwickeln Sie die Kette vom Primärschaden bis zur möglichen Einklemmung.", answer: "Mechanische Primärverletzung → Blutung/Ödem → intrakranielles Volumen und ICP steigen → zerebrale Perfusion sinkt → Ischämie und weiterer Sekundärschaden → mögliche Herniation. Hypoxie und Hypotonie verschärfen diese Kette." },
  { id: "sht-card-05", area: "Schweregrad", question: "Ordnen Sie die GCS-Bereiche den drei SHT-Schweregraden zu und nennen Sie typische Begleitmerkmale.", answer: "Leicht: GCS 13–15, Bewusstlosigkeit unter 15 Minuten. Mittelschwer: GCS 9–12, Bewusstlosigkeit über 15 Minuten und mögliche organische Schädigung. Schwer: GCS unter 9 mit tiefer, länger anhaltender Bewusstlosigkeit und schwerer Kontusion/Druckschädigung." },
  { id: "sht-card-06", area: "Hirndruck", question: "Welche Befunde bilden die Cushing-Reaktion und weshalb ist sie gefährlich?", answer: "Arterielle Hypertonie, Bradykardie beziehungsweise bradykarder Druckpuls und pathologische Atmung wie Cheyne-Stokes oder Biot. Sie weist auf fortgeschrittenen Hirndruck mit drohender Einklemmung hin." },
  { id: "sht-card-07", area: "Symptome", question: "Welche Befundkonstellation stützt präklinisch ein SHT mit möglicher intrakranieller Raumforderung?", answer: "Passender Mechanismus, Bewusstseinsänderung oder fallende GCS, Amnesie, Kopfschmerz, Erbrechen, Pupillendifferenz, fokale Ausfälle oder Krampfanfall sowie äußere Zeichen wie Brillenhämatom, Stufe oder Blut/klare Flüssigkeit aus Nase oder Ohr." },
  { id: "sht-card-08", area: "Erstmaßnahmen", question: "Strukturieren Sie die ersten Maßnahmen beim kritischen SHT.", answer: "STUVW und cABCDE, HWS manuell stabilisieren, Blutung kontrollieren, Oxygenierung und Atemweg sichern, Monitoring/BZ, kritische Einordnung, NEF früh, achsengerechte Rettung, zeitkritischer Transport und wiederholte GCS-, Pupillen- und Vitalwertkontrolle." },
  { id: "sht-card-09", area: "Beatmung", question: "Wann kommt eine milde Hyperventilation infrage und warum ist eine routinemäßige Hyperventilation problematisch?", answer: "Nur vorübergehend bei Zeichen einer drohenden Einklemmung. Unnötige Hypokapnie führt zur zerebralen Vasokonstriktion und kann die Hirnperfusion verschlechtern." },
  { id: "sht-card-10", area: "Trauma-VFA", question: "Welche Zeit- und Kreislaufziele sind beim führenden SHT besonders wichtig?", answer: "Load, go and treat; präklinische Gesamtzeit einschließlich Anfahrt und Transport unter 60 Minuten. Beim führenden oder isolierten SHT RRsys mindestens 90 mmHg, um einen zusätzlichen hypotonen Sekundärschaden zu vermeiden." },
  { id: "sht-card-11", area: "Analgesie", question: "Nennen Sie die drei verlangten Medikamentenverdünnungen beziehungsweise Konzentrationen für die intravenöse Anwendung.", answer: "Morphin 10 mg/1 ml plus 9 ml NaCl: 1 mg/ml. Esketamin 50 mg/2 ml plus 8 ml NaCl: 5 mg/ml. Midazolam 5 mg/5 ml unverdünnt: 1 mg/ml." },
  { id: "sht-card-12", area: "Entscheidungsfindung", question: "Warum müssen neurologischer Ausgangsbefund und Verlauf vor und nach Analgosedierung exakt dokumentiert werden?", answer: "Analgetika und Sedativa können Vigilanz, Atmung und neurologischen Befund verändern. Nur mit dokumentiertem Ausgangsbefund, Zeitpunkt, Dosis, Wirkung und serieller Reevaluation lassen sich Traumaentwicklung und Medikamenteneffekt beurteilen." },
  { id: "sht-card-13", area: "Schädelbasis", question: "Was ist das Battle-Zeichen und wie ordnen Sie es ein?", answer: "Eine retroaurikuläre beziehungsweise über dem Mastoid liegende Ekchymose nach Kopftrauma. Sie ist ein Hinweis auf eine mögliche Schädelbasisfraktur, besonders im Bereich der mittleren Schädelgrube, und kann zeitverzögert auftreten. Weitere Hinweise sind Brillenhämatom, Hämatotympanon sowie klare oder blutige Flüssigkeit aus Nase oder Ohr; das Fehlen dieser Zeichen schließt eine Fraktur nicht aus." },
];

const hypoglykaemieFlashcards: TrainingFlashcard[] = [
  { id: "hypo-card-01", area: "Definition", question: "Nennen Sie die Blutzucker-Richtwerte dieser Unterlage und ordnen Sie deren klinische Bedeutung ein.", answer: "Unter 50 mg/dl beziehungsweise etwa 2,8 mmol/l gilt als Hypoglykämie-Richtwert. Begleitsymptome können bereits bei 60–80 mg/dl auftreten; Messwert, Klinik und Verlauf müssen gemeinsam beurteilt werden." },
  { id: "hypo-card-02", area: "Anatomie", question: "Erklären Sie exokrine und endokrine Funktion des Pankreas und nennen Sie die drei Inselzelltypen.", answer: "Exokrin: Pankreassaft mit Verdauungsenzymen über den Ausführungsgang ins Duodenum. Endokrin: β-Zellen bilden Insulin, α-Zellen Glukagon und δ-Zellen Somatostatin; die Hormone gelangen direkt ins Blut." },
  { id: "hypo-card-03", area: "Physiologie", question: "Stellen Sie die gegensätzliche Wirkung von Insulin und Glukagon auf den Blutzucker dar.", answer: "Insulin ermöglicht die Glukoseaufnahme in Zielzellen und ihre Nutzung zur ATP-Gewinnung. Glukagon fördert in der Leber die Umwandlung von Glykogen zu Glukose und erhöht dadurch den Blutzucker." },
  { id: "hypo-card-04", area: "Pathophysiologie", question: "Leiten Sie die neurologische Gefahrenkette einer anhaltenden Hypoglykämie her.", answer: "Zerebraler Glukosemangel → rasche Entleerung verfügbarer Energiespeicher → neuronale Funktionsstörung → Verlust von Schutzreflexen, Krampfanfall und Bewusstlosigkeit → mögliche Nervenzellschädigung." },
  { id: "hypo-card-05", area: "Ursachen", question: "Welche Konstellationen führen bei einem behandelten Diabetes besonders häufig zur Hypoglykämie?", answer: "Missverhältnis aus blutzuckersenkender Medikation, Nahrungsaufnahme und Verbrauch: zu hohe Dosis, ausgelassene Mahlzeit, ungewohnte Belastung, Alkohol, Gastroenteritis, Pumpendefekt, Interaktion oder absichtliche Fehlanwendung." },
  { id: "hypo-card-06", area: "Symptome", question: "Trennen Sie autonome von neuroglykopenischen Zeichen und nennen Sie jeweils vier Beispiele.", answer: "Autonom: Heißhunger, Schwitzen, Zittern, Blässe, Unruhe, Tachykardie. Neuroglykopenisch: Schwindel, Kopfschmerz, Sehstörung, Verwirrtheit, Sprachstörung, fokales Defizit, Krampfanfall, Bewusstlosigkeit." },
  { id: "hypo-card-07", area: "Gefahren", question: "Welche unmittelbaren Gefahren entstehen durch Hypoglykämie und durch die intravenöse Glukosegabe?", answer: "Hypoglykämie: Krampf, Aspiration, Trauma, Koma, Hypothermie, Rhythmusstörung und Kreislaufstillstand. Glukose: Venenreizung, Hyperglykämie, möglicher Kaliumabfall und bei Paravasat Gewebsnekrose." },
  { id: "hypo-card-08", area: "Erstmaßnahmen", question: "Strukturieren Sie die ersten Maßnahmen bis zur Entscheidung über den Applikationsweg.", answer: "Eigenschutz, cABCDE, kritische Einordnung, frühe kapilläre BZ-Messung, Monitoring, Lagerung, Wärme, Sauerstoff nach Bedarf, Absaugbereitschaft und SAMPLERS. Dann Wachheit, Kooperation, Schutzreflexe und sicheren Gefäßzugang beurteilen." },
  { id: "hypo-card-09", area: "Anamnese", question: "Welche hypoglykämiespezifischen Punkte müssen innerhalb von SAMPLERS geklärt werden?", answer: "Diabetestyp, frühere Hypoglykämien, Insulin oder orale Antidiabetika mit Dosis und Zeitpunkt, Pumpe, letzte Mahlzeit, Alkohol, Belastung, Erbrechen/Diarrhö, Therapieänderung, Nieren-/Lebererkrankung, Infekt und mögliche Fehlanwendung." },
  { id: "hypo-card-10", area: "Differenzialdiagnosen", question: "Wie gehen Sie bei fokalem Defizit und bestätigter Hypoglykämie diagnostisch vor?", answer: "Hypoglykämie sofort behandeln, danach BZ und Neurologie reevaluierten. Persistiert das Defizit oder erklärt die klinische Reaktion den Befund nicht, werden Schlaganfall und weitere Differenzialdiagnosen parallel weiterverfolgt." },
  { id: "hypo-card-11", area: "VFA", question: "Stellen Sie den VFA-Entscheidungsweg für Erwachsene beziehungsweise Kinder über 50 kg dar.", answer: "Wach und kooperativ: 100 ml Glukose 20 % oder Substitution per os, insgesamt 20 g. Nicht wach: 100 ml Glukose 20 % langsam intravenös über sicheren Zugang. Kapilläre Kontrolle; bei fehlender Besserung einmalige Wiederholung i.v. und Suche nach anderen Ursachen." },
  { id: "hypo-card-12", area: "Verlauf", question: "Warum endet die Versorgung nicht mit einem normalisierten Einzelwert?", answer: "Glukose wirkt kurz; der Blutzucker kann erneut abfallen. Ursache, klinische Besserung, wiederholte kapilläre Werte, EKG, sichere Transportfähigkeit, Überwachung und vollständige Dokumentation bleiben entscheidend." },
  { id: "hypo-card-13", area: "Gegenregulation", question: "Wie reagiert ein gesunder Körper auf fallenden Blutzucker, und weshalb kann dieser Schutz versagen?", answer: "Zuerst sinkt die Insulinfreisetzung; anschließend erhöhen vor allem Glukagon und Adrenalin die hepatische Glykogenolyse und Glukoneogenese. Injiziertes Insulin lässt sich nicht abschalten, Sulfonylharnstoffe können die Insulinfreisetzung länger steigern, und bei wiederholten Hypoglykämien kann die Adrenalinwarnreaktion abgeschwächt sein." },
];

const hodentorsionFlashcards: TrainingFlashcard[] = [
  { id: "hoden-card-01", area: "Definition", question: "Definieren Sie die Hodentorsion und begründen Sie ihre Zeitkritik.", answer: "Hoden und Samenstrang drehen sich teilweise oder vollständig um die eigene Achse. Zuerst wird der venöse Abfluss, anschließend die arterielle Versorgung beeinträchtigt; ohne rasche operative Versorgung drohen Ischämie, Nekrose und Hodenverlust." },
  { id: "hoden-card-02", area: "Anatomie", question: "Welche Strukturen des Samenstrangs erklären die Folgen einer Torsion?", answer: "Der Samenstrang führt Samenleiter, Arterien, venösen Plexus und Nerven. Seine Rotation behindert zunächst den venösen Rückstrom und später den arteriellen Zufluss zum Hoden." },
  { id: "hoden-card-03", area: "Pathophysiologie", question: "Leiten Sie die Schädigungskaskade vollständig her.", answer: "Rotation → venöse Abflussbehinderung → Stauung und Schwellung → steigender Gewebedruck und eingeschränkter arterieller Zufluss → Ischämie → irreversible Nekrose." },
  { id: "hoden-card-04", area: "Risikokonstellation", question: "Welche Auslöser und Altersgruppen sind typisch?", answer: "Häufig idiopathisch im Schlaf, außerdem bei Sport, äußeren Reizen mit Cremasterkontraktion, Trauma oder erotischer Aktivität. Besonders betroffen sind Säuglinge sowie Jugendliche und junge Erwachsene; erhöhte Hodenbeweglichkeit begünstigt die Torsion." },
  { id: "hoden-card-05", area: "Symptome", question: "Welche Konstellation stützt die Arbeitsdiagnose Hodentorsion?", answer: "Plötzlicher starker einseitiger Hoden-, Leisten- oder Unterbauchschmerz, Schwellung und Druckschmerz, Hochstand, vegetative Zeichen sowie möglicher Seitenunterschied. Ger-, Brunzel- und Prehn-Zeichen können stützen, aber keines schließt allein sicher aus." },
  { id: "hoden-card-06", area: "Zeitfenster", question: "Welche Bedeutung hat das 4–6-Stunden-Fenster?", answer: "Mit zunehmender Ischämiedauer sinkt die Rettungswahrscheinlichkeit des Hodens erheblich. Verdacht, Analgesie und Transport werden deshalb parallel bearbeitet; Diagnostik darf die operative Versorgung nicht verzögern." },
  { id: "hoden-card-07", area: "Anamnese", question: "Welche spezifischen Angaben erheben Sie in OPQRST und SAMPLERS?", answer: "Exakter Beginn und Verlauf, Seite und Ausstrahlung, Stärke und Charakter, vorherige Episoden, Beginn im Schlaf, Sport oder Trauma, urologische Vorgeschichte/Operationen, Einzelhoden, Medikamente und letzte Nahrungsaufnahme." },
  { id: "hoden-card-08", area: "Diagnostik", question: "Was kann die Duplexsonografie zeigen und weshalb darf sie nicht falsch beruhigen?", answer: "Im Seitenvergleich können fehlende oder verminderte Perfusion und das Whirlpool-Zeichen sichtbar sein. Bei früher oder partieller Torsion kann arterielle Restperfusion bestehen; die Untersuchung darf bei hohem Verdacht die Operation nicht verzögern." },
  { id: "hoden-card-09", area: "Differenzialdiagnosen", question: "Nennen und gewichten Sie wichtige Differenzialdiagnosen des akuten Skrotums.", answer: "Hydatidentorsion, Epididymitis, Orchitis und Trauma; bei Unterbauch-/Leistenschmerz außerdem akutes Abdomen und Nierenkolik. Bei klinischem Torsionsverdacht bleibt die zeitkritische urologische Vorstellung vorrangig." },
  { id: "hoden-card-10", area: "Präklinik", question: "Strukturieren Sie die präklinische Versorgung bis zur Übergabe.", answer: "cABCDE, diskrete schonende Untersuchung im Seitenvergleich, NRS/OPQRST und SAMPLERS, Monitoring, Zugang und Analgesie nach VFA, Antiemese bei Bedarf, nüchtern belassen, früh urologisch voranmelden und ohne vermeidbare Verzögerung transportieren." },
  { id: "hoden-card-11", area: "VFA", question: "Welche Analgesiepfade zeigt VFA 35 bei traumatisch bedingtem starken Schmerz?", answer: "Nach cABCDE, Leitalgorithmen und OPQRST führt der traumatische Schmerzpfad – entsprechend der Vorgabe des zuständigen ÄLRD – zu Morphin nach VFA 38 oder Esketamin nach VFA 36. Überwachung und Transport werden fortgeführt." },
  { id: "hoden-card-12", area: "Esketamin", question: "Welche Sicherheitsmaßnahmen und Verlaufskontrollen verlangt die Esketamin-VFA?", answer: "Angepasste Sauerstoffgabe mit Ziel SpO₂ über 90 %, Beatmungsbereitschaft, EKG und Blutdruck, langsame intravenöse Gabe, dokumentierte NRS-Kontrollen nach fünf und zehn Minuten sowie kontinuierliches Monitoring und Transport." },
];

function shuffledFlashcards(sourceCards: TrainingFlashcard[], previous: TrainingFlashcard[] = []) {
  const next = [...sourceCards];
  for (let index = next.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [next[index], next[swapIndex]] = [next[swapIndex], next[index]];
  }
  if (previous.length === next.length && previous.every((card, index) => card.id === next[index].id)) next.push(next.shift()!);
  return next;
}

