function FlashcardTraining({ sourceCards, condition, onProgressChange }: { sourceCards: TrainingFlashcard[]; condition: string; onProgressChange: (progress: QuestionProgress) => void }) {
  const [cards, setCards] = useState<TrainingFlashcard[]>(() => shuffledFlashcards(sourceCards));
  const [index, setIndex] = useState(0);
  const [revealed, setRevealed] = useState(false);
  const [known, setKnown] = useState(0);
  const [finished, setFinished] = useState(false);
  const [lastAssessment, setLastAssessment] = useState<{ index: number; known: boolean; previous?: QuestionLearningRecord } | null>(null);
  const card = cards[index];

  const assess = (isKnown: boolean) => {
    setLastAssessment({ index, known: isKnown, previous: readQuestionProgress()[card.id] });
    onProgressChange(recordQuestionAnswer(card.id, isKnown));
    if (isKnown) setKnown((current) => current + 1);
    if (index === cards.length - 1) setFinished(true);
    else { setIndex((current) => current + 1); setRevealed(false); }
  };

  const undoAssessment = () => {
    if (!lastAssessment) return;
    const restoredCard = cards[lastAssessment.index];
    onProgressChange(restoreQuestionAnswer(restoredCard.id, lastAssessment.previous));
    setIndex(lastAssessment.index);
    setKnown((current) => lastAssessment.known ? Math.max(0, current - 1) : current);
    setFinished(false);
    setRevealed(true);
    setLastAssessment(null);
  };

  const restart = () => {
    setCards((current) => shuffledFlashcards(sourceCards, current));
    setIndex(0);
    setRevealed(false);
    setKnown(0);
    setFinished(false);
    setLastAssessment(null);
  };

  if (finished) return <section className="flashcard-training flashcard-result"><span className="eyebrow">Karteikarten abgeschlossen</span><h2>{known} von {cards.length} gewusst</h2><p>Deine Selbsteinschätzung wurde in der Lernstatistik gespeichert. „Noch üben“ setzt die betreffende Karte auf {formatProgressPercent(0)} zurück.</p><div className="flashcard-result-actions"><button className="secondary-button" onClick={undoAssessment}>Letzte Bewertung rückgängig</button><button className="primary-button" onClick={restart}>Neu starten und mischen</button></div></section>;

  return <section className="flashcard-training"><div className="flashcard-training-head"><span>Karte {index + 1} von {cards.length}</span><small>{condition} · Notfallsanitäter-Staatsexamen Thüringen</small></div><div className={`exam-flashcard ${revealed ? "revealed" : ""}`}><small>Prüfungsfrage</small><h2>{card.question}</h2>{revealed ? <div className="flashcard-answer"><small>Musterantwort aus dem Kapitel</small><p>{card.answer}</p></div> : <p>Formuliere deine Antwort zunächst vollständig, bevor du die Musterantwort aufdeckst.</p>}</div>{!revealed ? <button className="primary-button reveal-card" onClick={() => setRevealed(true)}>Musterantwort aufdecken</button> : <div className="flashcard-assessment"><button className="known" onClick={() => assess(true)}>✓ Gewusst</button><button className="practice" onClick={() => assess(false)}>↺ Noch üben</button></div>}{lastAssessment && <button className="undo-assessment" onClick={undoAssessment}>↶ Letzte Bewertung rückgängig</button>}</section>;
}

type ChoiceOption = { text: string; correct?: boolean };
type MultipleChoiceQuestion = { id: string; prompt: string; options: ChoiceOption[]; source: string; difficulty: 1 | 2 | 3; mode?: "single" | "multiple"; sourceTopic?: TrainingTopic; sourceTitle?: string };

const acsMultipleChoiceQuestions: MultipleChoiceQuestion[] = [
  { id: "acs-sc-01", prompt: "Welche Gruppe beschreibt das akute Koronarsyndrom vollständig?", options: [{ text: "Instabile Angina pectoris, NSTEMI und STEMI", correct: true }, { text: "Stabile Angina pectoris, Perikarditis und STEMI" }, { text: "NSTEMI, Myokarditis und Aortendissektion" }, { text: "STEMI, Lungenödem und stabile Angina pectoris" }], source: "Das ACS umfasst instabile Angina pectoris, NSTEMI und STEMI.", difficulty: 1 },
  { id: "acs-sc-02", prompt: "Welche Abfolge bildet die zelluläre Ischämiekaskade am besten ab?", options: [{ text: "Koronare Minderperfusion → Sauerstoffmangel → ATP-Mangel → Pumpenversagen und Ionenverschiebung → elektrische Instabilität → Nekrose", correct: true }, { text: "Koronare Minderperfusion → ATP-Anstieg → Kalziumabfall → stabile Membran → Nekrose" }, { text: "Koronarverschluss → gesteigerte aerobe Glykolyse → Laktatabbau → Hypertrophie" }, { text: "Sauerstoffmangel → verbesserte Ionenpumpenfunktion → Rhythmusstabilisierung → Narbenbildung" }], source: "Sauerstoffmangel führt zum Ausfall der aeroben ATP-Produktion, zum Ionenpumpenversagen, zu Rhythmusstörungen und schließlich zur Nekrose.", difficulty: 1 },
  { id: "acs-sc-03", prompt: "In welche Hauptäste teilt sich die linke Koronararterie?", options: [{ text: "Ramus circumflexus und Ramus interventricularis anterior", correct: true }, { text: "Ramus marginalis dexter und Ramus interventricularis posterior" }, { text: "A. pulmonalis und Ramus circumflexus" }, { text: "Ramus interventricularis posterior und V. cardiaca magna" }], source: "Die linke Koronararterie teilt sich in RCX und RIVA.", difficulty: 1 },
  { id: "acs-sc-04", prompt: "Welche Reihenfolge der kardialen Erregungsleitung ist korrekt?", options: [{ text: "Sinusknoten → AV-Knoten → His-Bündel → Tawara-Schenkel → Purkinje-Fasern", correct: true }, { text: "AV-Knoten → Sinusknoten → Purkinje-Fasern → His-Bündel → Tawara-Schenkel" }, { text: "Sinusknoten → His-Bündel → AV-Knoten → Purkinje-Fasern → Tawara-Schenkel" }, { text: "Purkinje-Fasern → Tawara-Schenkel → His-Bündel → AV-Knoten → Sinusknoten" }], source: "Die Erregung läuft vom Sinusknoten über AV-Knoten, His-Bündel und Tawara-Schenkel zu den Purkinje-Fasern.", difficulty: 1 },
  { id: "acs-sc-05", prompt: "Welche Kombination stützt die Arbeitsdiagnose ACS am stärksten?", options: [{ text: "Retrosternales Druckgefühl mit Ausstrahlung, kalter Schweiß, Übelkeit und Dyspnoe", correct: true }, { text: "Isolierter lageabhängiger Beinschmerz ohne vegetative Symptome" }, { text: "Fieber, produktiver Husten und seit Tagen zunehmende Halsschmerzen" }, { text: "Einseitige Beinschwellung ohne Thoraxbeschwerden oder Kreislaufreaktion" }], source: "Typisch sind retrosternaler Schmerz oder Druck, Ausstrahlung, Dyspnoe, Schwitzen, Übelkeit und Angst.", difficulty: 1 },
  { id: "acs-sc-06", prompt: "Welche Aussage zur ST-Strecke trifft zu?", options: [{ text: "Sie liegt zwischen Kammerdepolarisation und Repolarisation und ist bei der ACS-Beurteilung besonders wichtig", correct: true }, { text: "Sie entspricht ausschließlich der Vorhofkontraktion" }, { text: "Sie bildet nur die AV-Überleitungszeit ab" }, { text: "Sie ist identisch mit dem QRS-Komplex" }], source: "Die ST-Strecke liegt zwischen vollständiger Kammerdepolarisation und Repolarisation.", difficulty: 1 },
  { id: "acs-sc-07", prompt: "Bei welcher Konstellation muss besonders an ein atypisch präsentiertes ACS gedacht werden?", options: [{ text: "Frau mit Diabetes, Dyspnoe, Übelkeit und Schwäche ohne ausgeprägten Thoraxschmerz", correct: true }, { text: "Junger Patient mit isoliertem Knöcheltrauma" }, { text: "Patient mit lokaler Hautrötung ohne Allgemeinsymptome" }, { text: "Patient mit kurzzeitigem Nasenbluten und normalem Allgemeinzustand" }], source: "Frauen, Menschen mit Diabetes und Niereninsuffizienz können atypische Beschwerden ohne klassischen Thoraxschmerz zeigen.", difficulty: 2 },
  { id: "acs-sc-08", prompt: "Welches Zeit- und Technikziel gilt für das 12-Kanal-EKG beim akuten Koronarsyndrom?", options: [{ text: "12-Kanal-EKG mit 50 mm/s innerhalb von zehn Minuten", correct: true }, { text: "3-Kanal-EKG mit 25 mm/s innerhalb von 30 Minuten" }, { text: "12-Kanal-EKG erst nach vollständiger Schmerzfreiheit" }, { text: "Nur Pulsoxymetrie, sofern kein Kammerflimmern vorliegt" }], source: "VFA 12 fordert ein 12-Kanal-EKG mit 50 mm/s innerhalb von zehn Minuten.", difficulty: 2 },
  { id: "acs-sc-09", prompt: "Welche Aussagen zur Beurteilung von ST-Veränderungen sind richtig?", options: [{ text: "Der J-Punkt bildet den Übergang vom QRS-Komplex zur ST-Strecke", correct: true }, { text: "ST-Veränderungen werden in anatomisch zusammengehörigen Ableitungen bewertet", correct: true }, { text: "Die exakten Hebungsgrenzen hängen unter anderem von der Ableitung ab", correct: true }, { text: "Eine einzelne pauschale Millimetergrenze gilt unverändert für alle Ableitungen" }, { text: "Eine isolierte ST-Veränderung in einer beliebigen Ableitung beweist immer einen STEMI" }], source: "J-Punkt, benachbarte Ableitungen und die jeweils gültigen Grenzwerte werden gemeinsam beurteilt; das EKG bleibt Teil des klinischen Gesamtbilds.", difficulty: 2 },
  { id: "acs-sc-10", prompt: "Ein Patient zeigt typische ACS-Beschwerden, das erste 12-Kanal-EKG ist unauffällig. Welche Schlussfolgerung ist richtig?", options: [{ text: "ACS bleibt möglich; Klinik, Verlauf, Monitoring und geeigneter Transport bleiben entscheidend", correct: true }, { text: "ACS ist sicher ausgeschlossen und der Patient kann zu Hause bleiben" }, { text: "Ohne ST-Hebung ist keine weitere kardiale Diagnostik erforderlich" }, { text: "Ein unauffälliges EKG beweist eine gastroenterologische Ursache" }], source: "NSTEMI und instabile Angina können ohne anhaltende ST-Hebung auftreten; ein Einzel-EKG schließt ACS nicht aus.", difficulty: 2 },
  { id: "acs-sc-11", prompt: "Welche Kombination enthält ausschließlich Gegenanzeigen für Glyceroltrinitrat bei akutem Thoraxschmerz?", options: [{ text: "PDE-5-Hemmer innerhalb 48 Stunden, systolischer RR unter 120 mmHg, Verdacht auf Hinterwandinfarkt", correct: true }, { text: "Tachykardie, Übelkeit und Ausstrahlung in den Kiefer" }, { text: "Systolischer RR über 120 mmHg, fehlende PDE-5-Einnahme und Vorderwandinfarkt" }, { text: "Dyspnoe, Kaltschweißigkeit und pathologische ST-Hebung" }], source: "Kontraindikationen sind PDE-5-Hemmer in den letzten 48 Stunden, RRsys < 120 mmHg und der Verdacht auf Hinterwandinfarkt.", difficulty: 2 },
  { id: "acs-sc-12", prompt: "Welche Aussage zur Sauerstoffgabe entspricht dem Thüringer ACS-Basisalgorithmus?", options: [{ text: "Sauerstoff wird zielgerichtet mit einer Ziel-SpO₂ über 90 % eingesetzt", correct: true }, { text: "Jeder ACS-Patient erhält unabhängig von der Sättigung maximalen Sauerstofffluss" }, { text: "Sauerstoff ist bei ACS grundsätzlich kontraindiziert" }, { text: "Sauerstoff wird erst nach dem Herzkatheterlabor begonnen" }], source: "VFA 12 sieht eine zielgerichtete O₂-Gabe mit Ziel-SpO₂ > 90 % vor.", difficulty: 2 },
  { id: "acs-sc-13", prompt: "Ein Patient hat anhaltenden retrosternalen Druck, ST-Hebungen in benachbarten Ableitungen und bleibt kreislaufstabil. Welche Versorgungskette ist am besten begründet?", options: [{ text: "ACS-Algorithmus fortführen, verknüpfte VFA prüfen, Herzkatheterklinik früh informieren, EKG digital übermitteln und Direktübergabe anstreben", correct: true }, { text: "Transport bis zum Troponinergebnis am Einsatzort aufschieben" }, { text: "Nur Schmerz dokumentieren und ohne Monitoring transportieren" }, { text: "ST-Hebungen ignorieren, sofern die Sättigung normal ist" }], source: "VFA 12 fordert frühe Information einer Herzkatheterklinik, digitale EKG-Übermittlung, Direktübergabe, Monitoring und Transport.", difficulty: 3 },
  { id: "acs-sc-14", prompt: "Ein Patient mit Thoraxschmerz hat ein neurologisches Defizit, einseitig fehlenden Radialispuls und eine deutliche Blutdruckdifferenz. Welche Entscheidung ist am besten begründet?", options: [{ text: "Akute Aortendissektion vorrangig bedenken und vor ASS/Heparin die VFA-Kontraindikationen beachten", correct: true }, { text: "Befunde als typisches unkompliziertes ACS werten und Differenzialdiagnosen verwerfen" }, { text: "Neurologisches Defizit spricht sicher gegen eine Aortenerkrankung" }, { text: "Pulsdifferenz ist für die Therapieentscheidung ohne Bedeutung" }], source: "Neurologisches Defizit, Pulsdefizit und RR-Differenz sind Hinweise auf eine akute Aortendissektion; sie ist eine Kontraindikation.", difficulty: 3 },
  { id: "acs-sc-15", prompt: "Welcher Mechanismus erklärt den kardiogenen Schock nach ausgedehntem Myokardinfarkt am besten?", options: [{ text: "Nekrose reduziert die Kontraktionskraft, dadurch sinken Schlagvolumen, Herzzeitvolumen und Organperfusion", correct: true }, { text: "Ein isolierter Sauerstoffüberschuss steigert die Kontraktionskraft und verursacht Hypotonie" }, { text: "Eine venöse Obstruktion der Lungenstrombahn ist immer der primäre Mechanismus" }, { text: "Eine reine periphere Vasodilatation ohne Pumpversagen ist definitionsgemäß die Ursache" }], source: "Anhaltende Ischämie führt zur Myokardnekrose und verminderten Kontraktionskraft; Pumpversagen kann Hypotonie und kardiogenen Schock auslösen.", difficulty: 3 },
  { id: "acs-sc-16", prompt: "Ein Patient mit inferioren ST-Hebungen hat einen systolischen Blutdruck von 116 mmHg und berichtet eine PDE-5-Hemmer-Einnahme am Vortag. Wie ist Glyceroltrinitrat einzuordnen?", options: [{ text: "Nicht geben: Mehrere Kontraindikationen der Thüringer VFA liegen vor", correct: true }, { text: "Geben: Inferiore ST-Hebungen heben die Kontraindikationen auf" }, { text: "Geben: Nur ein systolischer Blutdruck unter 90 mmHg wäre relevant" }, { text: "Geben: PDE-5-Hemmer sind nur nach mehr als 48 Stunden kontraindiziert" }], source: "PDE-5-Hemmer innerhalb 48 Stunden, RRsys < 120 mmHg und Verdacht auf Hinterwandinfarkt sind Kontraindikationen.", difficulty: 3 },
  { id: "acs-sc-17", prompt: "Welche Aussage zur Merkhilfe MONA ist im Kontext dieses Kapitels korrekt?", options: [{ text: "MONA ist keine starre Reihenfolge; jede Maßnahme richtet sich nach Indikation, Kontraindikationen und Thüringer VFA", correct: true }, { text: "Alle vier Bestandteile müssen bei jedem ACS zwingend in derselben Reihenfolge gegeben werden" }, { text: "Eine normale SpO₂ verpflichtet zur routinemäßigen Sauerstoffgabe" }, { text: "Nitrate dürfen unabhängig von Blutdruck und Begleitmedikation gegeben werden" }], source: "MONA ist eine Merkhilfe; maßgeblich bleibt der konkrete Thüringer Algorithmus.", difficulty: 3 },
  { id: "acs-sc-18", prompt: "Welche Kombination passt zur Gabe von ASS und Heparin bei STEMI oder neuem Linksschenkelblock?", options: [{ text: "STEMI oder neu aufgetretener LSB plus Ausschluss aktiver Blutung, frischem Schlaganfall und akuter Aortendissektion vor ASS und Heparin", correct: true }, { text: "Jeder Thoraxschmerz erhält ASS und Heparin ohne Prüfung einer Aortendissektion" }, { text: "ASS und Heparin sind nur bei isolierter Übelkeit ohne EKG-Veränderungen vorgesehen" }, { text: "Ein frischer Schlaganfall ist eine Indikation für die Kombination" }], source: "Indikationen sind STEMI oder Linksschenkelblock; aktive Blutung, frischer Schlaganfall und akute Aortendissektion sind Kontraindikationen.", difficulty: 3 },
  { id: "acs-sc-19", mode: "multiple", prompt: "Welche Aussagen zur Sauerstoffbilanz des Myokards sind richtig?", options: [{ text: "Koronarfluss und Sauerstoffgehalt des Blutes bestimmen wesentlich das Angebot", correct: true }, { text: "Tachykardie erhöht den Bedarf und verkürzt gleichzeitig die Diastole", correct: true }, { text: "Hypoxämie oder schwere Anämie können das Angebot vermindern", correct: true }, { text: "Fieber oder starke Druckbelastung können den Bedarf erhöhen", correct: true }, { text: "Jedes Angebots-Bedarfs-Missverhältnis beweist einen akuten Plaquethrombus" }], source: "Angebot und Bedarf können aus verschiedenen Gründen aus dem Gleichgewicht geraten; nicht jede Ischämie ist automatisch ein atherothrombotisches Typ-1-ACS.", difficulty: 2 },
  { id: "acs-sc-20", mode: "multiple", prompt: "Welche Aussagen grenzen stabile und instabile Angina pectoris sinnvoll voneinander ab?", options: [{ text: "Reproduzierbare Beschwerden bei bekannter Belastung sprechen eher für eine stabile Angina", correct: true }, { text: "Neue Ruhebeschwerden oder eine deutliche Zunahme sprechen für Instabilität", correct: true }, { text: "Instabile Angina gehört zum Spektrum des akuten Koronarsyndroms", correct: true }, { text: "Eine Besserung in Ruhe schließt ein ACS sicher aus" }, { text: "Instabile Angina lässt sich präklinisch sicher vom NSTEMI trennen" }], source: "Dynamik und Auftreten in Ruhe kennzeichnen Instabilität; die definitive Abgrenzung zum NSTEMI erfordert klinische Diagnostik.", difficulty: 2 },
  { id: "acs-sc-21", mode: "multiple", prompt: "Welche Aussagen zur EKG-Beurteilung bei ACS sind richtig?", options: [{ text: "Der J-Punkt liegt am Übergang vom QRS-Komplex zur ST-Strecke", correct: true }, { text: "ST-Veränderungen werden in zusammengehörigen Ableitungen beurteilt", correct: true }, { text: "V3R/V4R können eine Rechtsherzbeteiligung erfassen", correct: true }, { text: "V7–V9 können einen posterioren Verschluss sichtbarer machen", correct: true }, { text: "Ein unauffälliges Einzel-EKG schließt ein ACS aus" }], source: "Ableitungszusammenhang, Zusatzableitungen und Verlauf sind für die Ischämiebeurteilung entscheidend.", difficulty: 3 },
  { id: "acs-sc-22", mode: "multiple", prompt: "Anhaltender Thoraxdruck bei zunächst unauffälligem EKG: Welche nächsten Schritte sind fachlich begründet?", options: [{ text: "Klinische Stabilität und Beschwerden wiederholt beurteilen", correct: true }, { text: "Kontinuierliches EKG-Monitoring und Defibrillationsbereitschaft fortführen", correct: true }, { text: "Bei anhaltenden oder wiederkehrenden Beschwerden ein weiteres 12-Kanal-EKG schreiben", correct: true }, { text: "Den zeitkritischen Transport bis zu einem präklinischen Troponinergebnis aussetzen" }, { text: "Eine koronare Ursache wegen des ersten EKGs verwerfen" }], source: "Das EKG ist eine Momentaufnahme; dynamische Verläufe verlangen Wiederholung, Monitoring und geeignete Zielklinikplanung.", difficulty: 3 },
  { id: "acs-sc-23", mode: "multiple", prompt: "Welche Aussagen beschreiben ASS und Heparin im Koronarthrombus korrekt?", options: [{ text: "ASS vermindert über irreversible COX-1-Hemmung die Thromboxan-A₂-Bildung", correct: true }, { text: "Heparin verstärkt die Wirkung von Antithrombin", correct: true }, { text: "Heparin hemmt dadurch besonders Thrombin und Faktor Xa", correct: true }, { text: "Beide Medikamente ersetzen die mechanische Reperfusion" }, { text: "ASS wirkt primär durch direkte Auflösung des Fibrinnetzes" }], source: "ASS greift an der Thrombozytenfunktion, Heparin an der plasmatischen Gerinnung an; die verschlossene Koronararterie muss dennoch reperfundiert werden.", difficulty: 3 },
  { id: "acs-sc-24", mode: "multiple", prompt: "Welche Aussagen zur Sauerstoffgabe und zu Nitraten sind korrekt?", options: [{ text: "Sauerstoff wird bei Hypoxämie beziehungsweise nach dem gültigen VFA-Ziel eingesetzt", correct: true }, { text: "Normoxämie allein begründet keine routinemäßige Hochdosis-Sauerstoffgabe", correct: true }, { text: "Eine Schmerzbesserung nach Nitro beweist keine koronare Ursache", correct: true }, { text: "PDE-5-Hemmer und Verdacht auf Hinterwandinfarkt müssen vor Nitro berücksichtigt werden", correct: true }, { text: "Nitro darf unabhängig von Blutdruck und Herzfrequenz diagnostisch getestet werden" }], source: "O₂ und Nitro sind indikationsgebundene Maßnahmen; Nitroreaktion ist kein diagnostischer Beweis.", difficulty: 3 },
  { id: "acs-sc-25", mode: "multiple", prompt: "Welche Aussagen zur heparininduzierten Thrombozytopenie Typ II treffen zu?", options: [{ text: "Sie ist immunvermittelt", correct: true }, { text: "Sie kann trotz fallender Thrombozyten neue Thrombosen verursachen", correct: true }, { text: "Eine bekannte HIT ist vor Heparingabe relevant", correct: true }, { text: "Sie ist gleichbedeutend mit einer harmlosen kurzfristigen Verdünnungsthrombozytopenie" }, { text: "Sie wird durch eine irreversible COX-1-Hemmung ausgelöst" }], source: "HIT Typ II aktiviert Thrombozyten immunologisch und ist wegen paradoxer Thrombosen gefährlich.", difficulty: 3 },
  ...supplementalQuestions.acs,
];

