function multipleChoiceQuestions(questionBank: MultipleChoiceQuestion[]) {
  return questionBank.map((question, questionIndex) => {
    const correctOptions = question.options.filter((option) => option.correct);
    if (correctOptions.length > 1) return { ...question, mode: "multiple" as const };

    const additionalCorrect = additionalCorrectAnswers[question.id];
    const originalCorrect = correctOptions[0];
    const distractors = question.options.filter((option) => !option.correct);
    const replacedDistractor = [...distractors].sort((left, right) => Math.abs(right.text.length - originalCorrect.text.length) - Math.abs(left.text.length - originalCorrect.text.length))[0];
    const retainedDistractors = distractors.filter((option) => option !== replacedDistractor);
    const longestRetained = [...retainedDistractors].sort((left, right) => right.text.length - left.text.length)[0];
    const longestCorrectLength = Math.max(originalCorrect.text.length, additionalCorrect.length);

    const options = question.options.map((option) => {
      if (option === replacedDistractor) return { text: additionalCorrect, correct: true };
      if (questionIndex % 2 === 0 && option === longestRetained && option.text.length <= longestCorrectLength) {
        const otherDistractor = retainedDistractors.find((candidate) => candidate !== option);
        return { text: `${option.text}; ${otherDistractor?.text.charAt(0).toLowerCase()}${otherDistractor?.text.slice(1)}` };
      }
      return option;
    });

    const focus = question.prompt.replace(/\?$/, "");
    return {
      ...question,
      prompt: `Zum Prüfungsaspekt „${focus}“: Welche Aussagen sind richtig?`,
      source: `${question.source} Zusätzlich richtig: ${additionalCorrect}`,
      mode: "multiple" as const,
      options,
    };
  });
}

function shuffledQuestions(questionBank: MultipleChoiceQuestion[], previous: MultipleChoiceQuestion[] = []) {
  const multipleBank = multipleChoiceQuestions(questionBank);
  const next = ([1, 2, 3] as const).flatMap((difficulty) => {
    const tier = multipleBank.filter((question) => question.difficulty === difficulty).map((question) => {
      const options = [...question.options];
      for (let index = options.length - 1; index > 0; index -= 1) {
        const swapIndex = Math.floor(Math.random() * (index + 1));
        [options[index], options[swapIndex]] = [options[swapIndex], options[index]];
      }
      return { ...question, options };
    });
    for (let index = tier.length - 1; index > 0; index -= 1) {
      const swapIndex = Math.floor(Math.random() * (index + 1));
      [tier[index], tier[swapIndex]] = [tier[swapIndex], tier[index]];
    }
    return tier;
  });
  if (previous.length === next.length && previous.every((question, index) => question.id === next[index].id)) next.push(next.shift()!);
  return next;
}

type StoredMultipleChoiceSession = {
  version: 1;
  questions: MultipleChoiceQuestion[];
  questionIndex: number;
  selections: Record<string, number[]>;
  answeredKeys: string[];
  correctAnswers: number;
  wrongQuestionIds: string[];
  roundSize: 5 | 10 | "all";
  skipStreak: number;
  updatedAt?: string;
};

function validateMultipleChoiceSession(saved: StoredMultipleChoiceSession | null, questionBank: MultipleChoiceQuestion[]) {
  if (!saved || saved.version !== 1 || !Array.isArray(saved.questions) || !saved.questions.length) return null;
  const availableIds = new Set(questionBank.map((question) => question.id));
  if (saved.questions.some((question) => !availableIds.has(question.id))) return null;
  return saved;
}

function readMultipleChoiceSession(storageKey: string, questionBank: MultipleChoiceQuestion[]) {
  if (!storageKey || typeof window === "undefined") return null;
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) || "null") as StoredMultipleChoiceSession | null;
    return validateMultipleChoiceSession(saved, questionBank);
  } catch { return null; }
}

function mcDayKey(date = new Date()) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

function MultipleChoiceQuiz({ questionBank, condition, onProgressChange, standalone = false, onTrainingStateChange, initialRoundSize = 10, autoStart = false, persistenceKey = "" }: { questionBank: MultipleChoiceQuestion[]; condition: string; onProgressChange: (progress: QuestionProgress) => void; standalone?: boolean; onTrainingStateChange?: (state: { current: number; total: number } | null) => void; initialRoundSize?: 5 | 10 | "all"; autoStart?: boolean; persistenceKey?: string }) {
  const resolvedPersistenceKey = persistenceKey || (condition === "Fällige Wiederholung" ? `${condition}:${mcDayKey()}:${autoStart ? questionBank[0]?.id || "einzeln" : "alle"}` : condition);
  const sessionStorageKey = `notsan-mc-session-v1:${resolvedPersistenceKey}`;
  const [restoredSession] = useState(() => readMultipleChoiceSession(sessionStorageKey, questionBank));
  const sessionUserId = getActiveLearningUserId();
  const [cloudHydratedUserId, setCloudHydratedUserId] = useState<string | null>(() => sessionUserId ? null : "guest");
  const [questions, setQuestions] = useState<MultipleChoiceQuestion[]>(() => restoredSession?.questions || (autoStart ? questionBank.slice(0, 1) : []));
  const [questionIndex, setQuestionIndex] = useState(() => restoredSession ? Math.min(restoredSession.questionIndex, restoredSession.questions.length - 1) : 0);
  const [selections, setSelections] = useState<Record<string, number[]>>(() => restoredSession?.selections || {});
  const [answeredKeys, setAnsweredKeys] = useState<string[]>(() => restoredSession?.answeredKeys || []);
  const [correctAnswers, setCorrectAnswers] = useState(() => restoredSession?.correctAnswers || 0);
  const [finished, setFinished] = useState(false);
  const [roundSize, setRoundSize] = useState<5 | 10 | "all">(() => restoredSession?.roundSize || initialRoundSize);
  const [wrongQuestions, setWrongQuestions] = useState<MultipleChoiceQuestion[]>(() => restoredSession ? restoredSession.questions.filter((question) => restoredSession.wrongQuestionIds.includes(question.id)) : []);
  const [bookmarks, setBookmarks] = useState<string[]>(() => readBookmarks());
  const [skipStreak, setSkipStreak] = useState(() => restoredSession?.skipStreak || 0);
  const [sessionQuestionBank] = useState(questionBank);
  const [sessionTrainingStateChange] = useState(() => onTrainingStateChange);
  // Question ids are repository-wide identities. Mixed rounds must not invent a
  // second progress/bookmark identity for the same question.
  const keyOf = (question: MultipleChoiceQuestion) => question.id;

  useEffect(() => {
    if (!sessionUserId) return;
    let active = true;
    void loadMultipleChoiceSession(sessionUserId, resolvedPersistenceKey).then((remote) => {
      if (!active) return;
      const remoteSession = validateMultipleChoiceSession(remote?.payload as StoredMultipleChoiceSession | null, sessionQuestionBank);
      const localTimestamp = restoredSession?.updatedAt || "";
      const remoteTimestamp = remote?.updatedAt || remoteSession?.updatedAt || "";
      if (remoteSession && remoteTimestamp > localTimestamp) {
        setQuestions(remoteSession.questions);
        setQuestionIndex(Math.min(remoteSession.questionIndex, remoteSession.questions.length - 1));
        setSelections(remoteSession.selections || {});
        setAnsweredKeys(remoteSession.answeredKeys || []);
        setCorrectAnswers(remoteSession.correctAnswers || 0);
        setWrongQuestions(remoteSession.questions.filter((question) => remoteSession.wrongQuestionIds.includes(question.id)));
        setRoundSize(remoteSession.roundSize || initialRoundSize);
        setSkipStreak(remoteSession.skipStreak || 0);
        setFinished(false);
        localStorage.setItem(sessionStorageKey, JSON.stringify({ ...remoteSession, updatedAt: remoteTimestamp }));
        sessionTrainingStateChange?.({ current: Math.min(remoteSession.answeredKeys.length + 1, remoteSession.questions.length), total: remoteSession.questions.length });
      }
      setCloudHydratedUserId(sessionUserId);
    }).catch(() => { if (active) setCloudHydratedUserId(sessionUserId); });
    return () => { active = false; };
  }, [initialRoundSize, resolvedPersistenceKey, restoredSession, sessionQuestionBank, sessionStorageKey, sessionTrainingStateChange, sessionUserId]);

  useEffect(() => {
    if (!sessionStorageKey) return;
    if (finished) {
      localStorage.removeItem(sessionStorageKey);
      if (sessionUserId && cloudHydratedUserId === sessionUserId) void deleteMultipleChoiceSession(sessionUserId, resolvedPersistenceKey).catch(() => undefined);
      return;
    }
    if (!questions.length) return;
    if (sessionUserId && cloudHydratedUserId !== sessionUserId) return;
    const updatedAt = new Date().toISOString();
    const session: StoredMultipleChoiceSession = { version: 1, questions, questionIndex, selections, answeredKeys, correctAnswers, wrongQuestionIds: wrongQuestions.map((question) => question.id), roundSize, skipStreak, updatedAt };
    localStorage.setItem(sessionStorageKey, JSON.stringify(session));
    if (!sessionUserId) return;
    const timer = window.setTimeout(() => { void saveMultipleChoiceSession(sessionUserId, resolvedPersistenceKey, session, updatedAt).catch(() => undefined); }, 500);
    return () => window.clearTimeout(timer);
  }, [answeredKeys, cloudHydratedUserId, correctAnswers, finished, questionIndex, questions, resolvedPersistenceKey, roundSize, selections, sessionStorageKey, sessionUserId, skipStreak, wrongQuestions]);

  useEffect(() => {
    if (!restoredSession?.questions.length) return;
    onTrainingStateChange?.({ current: Math.min(restoredSession.answeredKeys.length + 1, restoredSession.questions.length), total: restoredSession.questions.length });
  }, [onTrainingStateChange, restoredSession]);

  const start = () => {
    const shuffled = shuffledQuestions(questionBank, questions);
    const limit = roundSize === "all" ? shuffled.length : Math.min(roundSize, shuffled.length);
    setQuestions(shuffled.slice(0, limit)); setQuestionIndex(0); setSelections({}); setAnsweredKeys([]); setCorrectAnswers(0); setFinished(false); setWrongQuestions([]); setSkipStreak(0);
    onTrainingStateChange?.({ current: 1, total: limit });
  };
  const question = questions[questionIndex];
  const currentKey = question ? keyOf(question) : "";
  const selected = selections[currentKey] || [];
  const answered = answeredKeys.includes(currentKey);
  const evaluate = () => {
    if (!question || answered) return;
    const correct = question.options.flatMap((option, index) => option.correct ? [index] : []);
    const isCorrect = selected.length === correct.length && selected.every(index => correct.includes(index));
    setAnsweredKeys(current => [...current, currentKey]); setSkipStreak(0);
    if (isCorrect) setCorrectAnswers(current => current + 1); else setWrongQuestions(current => [...current, question]);
    onProgressChange(recordQuestionAnswer(currentKey, isCorrect));
  };
  const next = () => {
    const open = questions.findIndex((item, index) => index > questionIndex && !answeredKeys.includes(keyOf(item)));
    const wrapped = questions.findIndex(item => !answeredKeys.includes(keyOf(item)));
    const target = open >= 0 ? open : wrapped;
    if (target < 0) { setFinished(true); return; }
    setQuestionIndex(target); onTrainingStateChange?.({ current: answeredKeys.length + 1, total: questions.length });
  };
  const skip = () => {
    if (answered) return;
    const nextStreak = skipStreak + 1; setSkipStreak(nextStreak);
    if (nextStreak >= questions.length - answeredKeys.length) return;
    const open = questions.findIndex((item, index) => index > questionIndex && !answeredKeys.includes(keyOf(item)));
    setQuestionIndex(open >= 0 ? open : questions.findIndex(item => !answeredKeys.includes(keyOf(item))));
  };
  const toggleBookmark = () => {
    const next = bookmarks.includes(currentKey) ? bookmarks.filter(key => key !== currentKey) : [...bookmarks, currentKey];
    setBookmarks(next); writeBookmarks(next);
  };
  if (!questions.length) return <div className={`ai-question-panel quiz-launch ${standalone ? "standalone" : ""}`}><div><span className="eyebrow">{standalone ? "MC-Training" : "Nach dem Lesen"}</span><h2>Multiple-Choice-Runde</h2><p>Fragen und Antworten werden bei jedem Neustart neu gemischt. Dein Lernstand wird erst beim Prüfen einer Antwort verändert.</p><fieldset className="round-size"><legend>Umfang der Runde</legend>{([5,10,"all"] as const).map(size => <button type="button" key={size} className={roundSize === size ? "active" : ""} onClick={() => setRoundSize(size)}>{size === "all" ? `Alle (${questionBank.length})` : `${Math.min(size, questionBank.length)} Fragen`}</button>)}</fieldset></div><button className="primary-button" onClick={start}>Training starten</button></div>;
  const unanswered = questions.length - answeredKeys.length;
  if (finished) return <section className={`chapter-quiz quiz-result ${standalone ? "standalone" : ""}`}><span className="eyebrow">Rundenergebnis</span><h2>{correctAnswers} richtig · {wrongQuestions.length} falsch · {unanswered} unbeantwortet</h2><p>Übersprungene Fragen wurden nicht bewertet und haben deinen Lernstand nicht verändert.</p><div className="quiz-result-actions">{unanswered > 0 && <button onClick={() => { setFinished(false); setSkipStreak(0); setQuestionIndex(questions.findIndex(item => !answeredKeys.includes(keyOf(item)))); onTrainingStateChange?.({ current: answeredKeys.length + 1, total: questions.length }); }}>Offene Fragen beantworten</button>}<button className="primary-button" onClick={start}>Neue Runde</button></div></section>;
  const correctIndices = question.options.flatMap((option,index) => option.correct ? [index] : []);
  const wasCorrect = answered && selected.length === correctIndices.length && selected.every(index => correctIndices.includes(index));
  const bookmarked = bookmarks.includes(currentKey);
  return <section className={`chapter-quiz ${standalone ? "standalone" : ""}`}><div className="chapter-quiz-head"><div><span className="choice-type-badge multiple">Multiple Choice</span><small>{question.sourceTitle || condition} · {answeredKeys.length} bearbeitet · {unanswered} offen · {questions.length} insgesamt</small></div><button className={`bookmark-question ${bookmarked ? "active" : ""}`} type="button" onClick={toggleBookmark} aria-pressed={bookmarked} aria-label={bookmarked ? "Frage nicht mehr merken" : "Frage merken"}>{bookmarked ? "★ Gemerkt" : "☆ Merken"}</button></div><h2>{question.prompt}</h2><div className="multiple-choice-actions">{question.options.map((option,index) => { const chosen=selected.includes(index); const answerClass=answered ? option.correct ? "correct" : chosen ? "wrong" : "dimmed" : chosen ? "selected" : ""; return <button key={option.text} type="button" className={answerClass} disabled={answered} aria-pressed={chosen} onClick={() => setSelections(current => ({...current,[currentKey]:toggleMultipleChoiceSelection(current[currentKey] || [], index)}))}><span>{String.fromCharCode(65+index)}</span><b>{option.text}</b></button>})}</div>{!answered && <div className="quiz-open-actions"><button className="check-multiple-answer" onClick={evaluate} disabled={!selected.length}>Auswahl prüfen</button><button type="button" onClick={skip}>Später beantworten</button>{skipStreak >= unanswered && <button type="button" onClick={() => { setFinished(true); onTrainingStateChange?.(null); }}>Runde mit offenen Fragen beenden</button>}</div>}{answered && <div className={`quiz-source-answer ${wasCorrect ? "correct" : "wrong"}`}><b>{wasCorrect ? "Richtig beantwortet" : "Falsch beantwortet"}</b><p>{question.source}</p><div className="quiz-explanation-actions">{question.sourceTopic && <button type="button" onClick={() => window.open(`/muendlich/${question.sourceTopic}?return=training`, "notsan-reading")}>Kapitel nachlesen</button>}<button onClick={next}>{unanswered ? "Nächste offene Frage" : "Ergebnis anzeigen"} →</button></div></div>}</section>;
}
function QuestionPanel() {
  return <div className="ai-question-panel"><div><span className="eyebrow">Nach dem Lesen</span><h2>Fragen aus diesem Kapitel erstellen</h2><p>Die KI-Funktion wird später ausschließlich den hinterlegten Kapitelinhalt als Grundlage verwenden.</p></div><button className="primary-button" disabled>KI-Fragen erstellen</button></div>;
}

