function ChapterProgressCard({ title, category, questions, progress, onTrain }: { title: string; category: string; questions: MultipleChoiceQuestion[]; progress: QuestionProgress; onTrain: (mode: Exclude<ReviewMode, null>) => void }) {
  const records = questions.map((question) => progress[question.id]);
  const answered = records.filter(Boolean);
  const wrong = answered.filter((record) => record.correctCount === 0).length;
  const once = answered.filter((record) => record.correctCount === 1).length;
  const twice = answered.filter((record) => record.correctCount === 2).length;
  const mastered = answered.filter((record) => record.correctCount === 3).length;
  const metrics = progressMetrics(progress, questions.map((question) => question.id));
  /* Alte Kartenansicht ohne getrennten Bearbeitungsfortschritt.
  return <section className="chapter-progress-card"><div className="chapter-progress-main"><div className="chapter-progress-title"><span>{category}</span><h2>{title}</h2><p>{answered.length} von {questions.length} Fragen begonnen. Hier erscheinen nur gezielte Wiederholungsstapel.</p></div><div className="chapter-score"><b>{answered.length}/{questions.length}</b><span>bearbeitet · Festigung {average}% von allen verfügbaren Stufen</span></div></div><div className="chapter-progress-track"><span style={{ width: `${average}%` }} /></div><div className="review-action-grid"><button className="wrong" onClick={() => onTrain("wrong")} disabled={!wrong}><span>✕</span><div><b>{wrong} falsche</b><small>{wrong ? "Jetzt wiederholen" : "Keine offen"}</small></div></button><button className="once" onClick={() => onTrain("once")} disabled={!once}><span>1×</span><div><b>{once} einmal richtig</b><small>{once ? "Jetzt festigen" : "Keine offen"}</small></div></button><button className="twice" onClick={() => onTrain("twice")} disabled={!twice}><span>2×</span><div><b>{twice} zweimal richtig</b><small>{twice ? "Freiwillig festigen" : "Keine offen"}</small></div></button><div className="mastered-count"><span>3×</span><div><b>{mastered} gefestigt</b><small>Weiterhin freiwillig im vollständigen Kapitel übbar</small></div></div></div></section>;
  */
  return <section className="chapter-progress-card"><div className="chapter-progress-main"><div className="chapter-progress-title"><span>{category}</span><h2>{title}</h2><p>{answered.length} von {questions.length} Fragen bearbeitet. Hier erscheinen nur gezielte Wiederholungsstapel.</p></div><div className="chapter-score"><b>{formatProgressPercent(metrics.completionPercent)}</b><span>Bearbeitungsfortschritt · Festigung {formatProgressPercent(metrics.consolidationPercent)} separat</span></div></div><div className="chapter-progress-track"><span style={{ width: `${metrics.completionPercent}%` }} /></div><div className="review-action-grid"><button className="wrong" onClick={() => onTrain("wrong")} disabled={!wrong}><span>✕</span><div><b>{wrong} falsche</b><small>{wrong ? "Jetzt wiederholen" : "Keine offen"}</small></div></button><button className="once" onClick={() => onTrain("once")} disabled={!once}><span>1×</span><div><b>{once} einmal richtig</b><small>{once ? "Jetzt festigen" : "Keine offen"}</small></div></button><button className="twice" onClick={() => onTrain("twice")} disabled={!twice}><span>2×</span><div><b>{twice} zweimal richtig</b><small>{twice ? "Freiwillig festigen" : "Keine offen"}</small></div></button><div className="mastered-count"><span>3×</span><div><b>{mastered} gefestigt</b><small>Weiterhin freiwillig im vollständigen Kapitel übbar</small></div></div></div></section>;
}

